import json
import subprocess
import sys
from pathlib import Path

from agents import function_tool

SCRIPT = Path("/opt/marketing/tools/spam_score.py")


@function_tool
def run_template_spam_check(template_path: str, threshold: float = 5.0, timeout_s: int = 60) -> dict:
    p = str(template_path).strip()
    if not p.endswith((".html", ".htm")):
        return {"ok": False, "error": "template must be an .html file"}
    if threshold <= 0:
        return {"ok": False, "error": "threshold must be positive"}
    cmd = [
        sys.executable,
        "-I",
        str(SCRIPT),
        "--template",
        p,
        "--format",
        "json",
    ]
    try:
        r = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout_s,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return {"ok": False, "error": f"timed out after {timeout_s}s"}
    if r.returncode != 0:
        return {"ok": False, "error": r.stderr.strip()[-500:]}
    try:
        d = json.loads(r.stdout)
    except json.JSONDecodeError:
        return {"ok": False, "error": "script returned invalid JSON"}
    s = float(d.get("score", 0))
    rules = d.get("rules", [])
    top = sorted(rules, key=lambda x: x.get("points", 0), reverse=True)[:10]
    return {
        "ok": True,
        "score": s,
        "threshold": threshold,
        "passed": s <= threshold,
        "flagged": [{"rule": x.get("name"), "points": x.get("points")} for x in top],
    }

import json
import os
import subprocess
import sys

import requests
from agents import function_tool

API = "https://api.esp.example.com/v3"
KEY = os.environ.get("ESP_API_KEY", "")
BUILDER = "/opt/marketing/tools/build_segment.py"


@function_tool
def build_and_send_segment_batch(campaign_id: str, segment: str, subject: str, max_recipients: int = 5000) -> dict:
    if not campaign_id or not segment:
        return {"ok": False, "error": "campaign_id and segment are required"}
    if not subject.strip():
        return {"ok": False, "error": "subject is empty"}
    if max_recipients < 1 or max_recipients > 100000:
        return {"ok": False, "error": "max_recipients out of range"}
    cmd = [
        sys.executable,
        "-I",
        BUILDER,
        "--segment",
        segment,
        "--limit",
        str(max_recipients),
        "--json",
    ]
    r = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
    if r.returncode != 0:
        return {"ok": False, "error": r.stderr.strip()[-500:]}
    try:
        rc = json.loads(r.stdout)
    except json.JSONDecodeError:
        return {"ok": False, "error": "builder returned invalid JSON"}
    if not rc:
        return {"ok": False, "error": "segment produced no recipients"}
    body = {
        "campaign_id": campaign_id,
        "subject": subject,
        "recipients": rc,
    }
    h = {"Authorization": f"Bearer {KEY}", "Content-Type": "application/json"}
    resp = requests.post(f"{API}/batches", json=body, headers=h, timeout=60)
    if resp.status_code >= 400:
        return {"ok": False, "status": resp.status_code, "error": resp.text[:500]}
    d = resp.json()
    return {
        "ok": True,
        "batch_id": d.get("id"),
        "recipients": len(rc),
        "status": d.get("status"),
    }
